package net.officefloor.hq.app.template;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimTemplateController {

    /** A template as the screen shows it; the amount always carries two decimals. */
    public record TemplateView(Long id, String name, String amount, String note) {
        static TemplateView of(ClaimTemplate t) {
            return new TemplateView(t.getId(), t.getName(), t.getAmount().toPlainString(), t.getNote());
        }
    }

    public record TemplateForm(@NotNull @Size(max = 140) String name, @NotNull BigDecimal amount,
            @Size(max = 500) String note) {
    }

    public record FromTemplateForm(@NotNull @Size(max = 140) String template) {
    }

    private final ClaimTemplateService service;

    public ClaimTemplateController(ClaimTemplateService service) {
        this.service = service;
    }

    /** The sheet's claim templates, by name. */
    @GetMapping("/claim-templates")
    public List<TemplateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.list(sheetId).stream().map(TemplateView::of).toList();
    }

    /** Save a template; saving a name again replaces it. */
    @PostMapping("/claim-templates")
    public TemplateView save(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody TemplateForm form, @SessionAttribute(SessionController.USER) String user) {
        return TemplateView.of(service.save(user, sheetId, form.name(), form.amount(), form.note()));
    }

    /** Add a draft claim for the person from a template, as the claim form adds one with no date. */
    @PostMapping("/people/{personId}/claims/from-template")
    public ClaimView addClaim(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long personId, @Valid @RequestBody FromTemplateForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.addClaim(user, sheetId, personId, form.template()));
    }
}
package net.officefloor.hq.app.template;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/** A claim template on a sheet: a name, and the amount and note a claim made from it starts with. */
@Entity
@Table(name = "claim_template")
public class ClaimTemplate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "note", nullable = false)
    private String note;

    protected ClaimTemplate() {
    }

    public ClaimTemplate(String sheetId, String name, BigDecimal amount, String note) {
        this.sheetId = sheetId;
        this.name = name;
        this.amount = amount;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }
}
package net.officefloor.hq.app.template;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimTemplateRepository extends JpaRepository<ClaimTemplate, Long> {

    List<ClaimTemplate> findBySheetIdOrderByNameAsc(String sheetId);

    Optional<ClaimTemplate> findBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.template;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's claim templates. A claim is added from one as the claim form adds one with the template's amount and
 * note at that moment and no date; a later change to the template leaves the claims made from it as they are.
 */
@Service
public class ClaimTemplateService {

    private final ClaimTemplateRepository templates;
    private final ClaimService claims;
    private final SheetService sheets;
    private final Audit audit;

    public ClaimTemplateService(ClaimTemplateRepository templates, ClaimService claims, SheetService sheets,
            Audit audit) {
        this.templates = templates;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's templates, by name. */
    @Transactional(readOnly = true)
    public List<ClaimTemplate> list(String sheetId) {
        return templates.findBySheetIdOrderByNameAsc(sheetId);
    }

    /**
     * Saves a template under its name, trimmed, replacing one already saved under it. Refused when the name is blank,
     * or the amount is one the claim form refuses without a claim to correct: negative, or with more than two
     * decimals.
     */
    @Transactional
    public ClaimTemplate save(String by, String sheetId, String name, BigDecimal amount, String note) {
        String key = name == null ? "" : name.strip();
        if (key.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Enter a template name.");
        }
        if (amount == null || amount.signum() < 0 || amount.stripTrailingZeros().scale() > 2) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "Enter an amount of at least 0 with up to two decimals.");
        }
        BigDecimal scaled = amount.setScale(2, RoundingMode.UNNECESSARY);
        String text = note == null ? "" : note.strip();
        sheets.lock(sheetId);
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, key)
                .orElseGet(() -> new ClaimTemplate(sheetId, key, scaled, text));
        template.setAmount(scaled);
        template.setNote(text);
        ClaimTemplate saved = templates.saveAndFlush(template);
        audit.recordOnCommit("TEMPLATE_SAVED sheet=" + sheetId + " by=" + by + " name=" + key + " amount="
                + scaled.toPlainString() + " note=" + text);
        return saved;
    }

    /** Adds a draft claim for the person from the named template, by every rule of the claim form. */
    @Transactional
    public Claim addClaim(String by, String sheetId, Long personId, String name) {
        String key = name == null ? "" : name.strip();
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, key)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No template " + key + "."));
        return claims.add(by, sheetId, personId, template.getAmount(), null, template.getNote(), null, null, null);
    }
}
-- The sheet's claim templates, each name at most once: a name, an amount and a note a claim can be added from.
-- A claim made from one copies its amount and note, so a later change to the template leaves it as it was.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(140)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    note     VARCHAR(500)   NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX claim_template_name ON claim_template (sheet_id, name);
-- A person merged in on arriving from another sheet brings their name and aliases as aliases, which may equal one the
-- person merged into already has but for case; an alias is no longer kept unique on its sheet by the store, the app
-- refusing one that is already a name or alias there.
DROP INDEX person_alias_sheet_alias;
CREATE INDEX person_alias_sheet_alias ON person_alias (sheet_id, alias_key);
